import {flatten} from './delta.mjs';
import {usage} from './persistence.mjs';
const format=bytes=>bytes>=1048576?(bytes/1048576).toFixed(2)+' MB':Math.ceil(bytes/1024)+' KB';
async function mount(){const body=document.querySelector('#editor-body');if(!body||!document.querySelector('#save-profile')||body.querySelector('#storage-capacity'))return;const panel=document.createElement('section');panel.id='storage-capacity';panel.className='capacity-panel';panel.innerHTML='<h3>Dung lượng dữ liệu</h3><p role="status">Đang kiểm tra bộ nhớ…</p>';body.append(panel);try{const bytes=value=>new TextEncoder().encode(JSON.stringify(value)).length,total=bytes(data),largest=Math.max(0,...Object.values(flatten(data)).map(bytes)),device=await usage();if(!panel.isConnected)return;panel.innerHTML='<h3>Dung lượng dữ liệu</h3><label>Dữ liệu đồng bộ: '+format(total)+' / 20 MB<meter min="0" max="20000000" value="'+total+'"></meter></label><p>Bản ghi lớn nhất: '+format(largest)+' / 1,5 MB</p><p>Bộ nhớ trình duyệt: '+format(device.usage||0)+(device.quota?' / '+format(device.quota):'')+'</p><p>Phác thảo được lưu riêng trên R2 khi có mạng. Bản nháp được lưu trong IndexedDB.</p><button class="btn" type="button">Ưu tiên giữ bản lưu trên thiết bị</button><small role="status"></small>';panel.querySelector('button').onclick=async()=>{const ok=await navigator.storage?.persist?.();panel.querySelector('small').textContent=ok?'Trình duyệt đã cho phép lưu bền vững.':'Trình duyệt chưa cấp lưu bền vững. Bạn vẫn có thể xuất JSON để sao lưu.';};}catch{panel.querySelector('[role=status]').textContent='Chưa đọc được dung lượng. Bạn có thể xuất JSON để sao lưu.';}}
new MutationObserver(mount).observe(document.querySelector('#editor-body'),{childList:true});mount();
